DECLARE 
@ReceSheetNo VARCHAR(32),
@DetailNo VARCHAR(32),
@LotNo VARCHAR(50),
@Count int,
@Message VARCHAR(200),
@ireturn INT,
@JobSheetNo VARCHAR(50),
@SheetKind SMALLINT,
@CustJobNo VARCHAR(100),
@NUM1 INT,
@NUM2 INT,
@NUM3 INT

declare mycursor cursor for SELECT ReceSheetNo,SheetKind,LotNo,DetailNo FROM dye.GrayReturnApplyDetail INNER JOIN dye.GrayReturnApply ON dye.GrayReturnApply.SheetSeries = dye.GrayReturnApplyDetail.SheetSeries
where GrayReturnApply.SheetSeries=@SheetSeries

open mycursor
 fetch next from mycursor into @ReceSheetNo,@SheetKind,@LotNo,@DetailNo
if(@@fetch_status<>0)
begin
	SELECT  @ireturn=1,@Message=''
end
else
begin
	while(@@fetch_status = 0)
	BEGIN

	SELECT @Count=COUNT(*) FROM dye.GrayInDetail WHERE GrayApplyNo=@DetailNo
		   if @Count > 0
			  Begin
			   select @ireturn=0,@Message='批号【'+ @LotNo+'】已经退货出库，不能反审！'
			  END			   		
           else
             Begin
              select @ireturn=1,@Message=''
             END

	   fetch next from mycursor into @ReceSheetNo,@SheetKind,@LotNo,@DetailNo
	END 
    END 

close mycursor	

deallocate mycursor

select @ireturn,@Message

