DECLARE
@SheetNo VARCHAR(32),
@Count1 INT,
@Count2 INT,
@Count3 INT,
@DesigneeID VARCHAR(32),
@Name VARCHAR(32),
@Creater  VARCHAR(32),
@Modifyer VARCHAR(32),
@Approver VARCHAR(32),
@Message VARCHAR(200),
@ireturn INT 

DECLARE  mycursor CURSOR  FOR   
SELECT  
SheetSeries,SheetNo,DesigneeID
FROM dye.RequestLimit
WHERE SheetSeries=@SheetSeries

OPEN  mycursor
FETCH  NEXT  FROM  mycursor INTO  @SheetSeries,@SheetNo,@DesigneeID
WHILE (@@fetch_status = 0)

BEGIN
    SELECT @Name=Name FROM  dye.h_Employee WHERE EmpID=@DesigneeID
    	   
	IF @EmpID<>@DesigneeID
    BEGIN 
    SELECT  @ireturn=0,@Message='单号:['+@SheetNo+']，指定审核人:['+@Name+']才能审核,请检查!'
    END
    ELSE
    BEGIN 
    SELECT  @ireturn=1,@Message=''
    END
	
FETCH  NEXT  FROM  mycursor INTO  @SheetSeries,@SheetNo,@DesigneeID
END 

CLOSE  mycursor  

DEALLOCATE  mycursor

SELECT  @ireturn,@Message

